-- ---------------------------------------------------------------- hdr_pre_upgrade.sql
BEGIN
  BEGIN
    DBMS_SCHEDULER.DISABLE('HDR_TICK', force => TRUE);
    DBMS_SCHEDULER.STOP_JOB('HDR_TICK', force => FALSE);
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE NOT IN (-27475, -27476, -27366) THEN   -- no such job / not running
      RAISE;
    END IF;
  END;
  BEGIN
    EXECUTE IMMEDIATE q'[MERGE INTO HDR_SETTINGS t USING (SELECT 'maintenance' k FROM DUAL) s ON (t.SKEY = s.k)
                         WHEN MATCHED THEN UPDATE SET SVALUE = 'Y'
                         WHEN NOT MATCHED THEN INSERT (SKEY, SVALUE) VALUES (s.k, 'Y')]';
    COMMIT;
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE <> -942 THEN   -- a first install: no settings yet
      RAISE;
    END IF;
  END;
END;
/

-- ---------------------------------------------------------------- hader_interface.sql
DECLARE
  n NUMBER;
  m NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_PUNCHES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_PUNCHES (
        PUNCH_ID      NUMBER(12)     NOT NULL,          -- Hader's punch number (unique)
        EMP_CODE      VARCHAR2(30)   NOT NULL,          -- employee number on the terminal
        PUNCH_TIME    DATE           NOT NULL,
        PUNCH_STATE   NUMBER(3),                        -- 0 in, 1 out, 2 break out, 3 break in, 4 OT in, 5 OT out
        STATE_NAME    VARCHAR2(30),
        VERIFY_TYPE   VARCHAR2(30),                     -- fingerprint, face, palm, card, password...
        DEVICE_SN     VARCHAR2(50),
        DEVICE_NAME   VARCHAR2(100),
        SOURCE        VARCHAR2(10),                     -- device / tcp / manual / import
        TEMPERATURE   NUMBER(4,1),                      -- the body temperature a thermal terminal took
        UPLOADED_AT   DATE,                             -- reached the server (the terminal's clock)
        ORIG_TIME     DATE,                             -- its time before a clock fix
        FIXED_AT      DATE,
        CREATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_PUNCHES_PK PRIMARY KEY (PUNCH_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_PUNCHES_EMP_IX ON HADER_PUNCHES (EMP_CODE, PUNCH_TIME)';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_PUNCHES_TIME_IX ON HADER_PUNCHES (PUNCH_TIME)';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_ATT_DAILY';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_ATT_DAILY (
        EMP_CODE      VARCHAR2(30)   NOT NULL,
        ATT_DATE      DATE           NOT NULL,          -- the day (time part 00:00)
        STATUS        VARCHAR2(20),                     -- present, late, early, late_early, absent, leave,
                                                        -- holiday, off, incomplete, unscheduled, pending
        STATUS_AR     VARCHAR2(40),
        STATUS_EN     VARCHAR2(40),
        TIMETABLE     VARCHAR2(60),
        SCHED_IN      DATE,
        SCHED_OUT     DATE,
        CLOCK_IN      DATE,
        CLOCK_OUT     DATE,
        REQUIRED_MIN  NUMBER(6),                        -- minutes the employee should have worked
        WORKED_MIN    NUMBER(6),
        LATE_MIN      NUMBER(6),
        EARLY_MIN     NUMBER(6),
        OT_MIN        NUMBER(6),
        LEAVE_MIN     NUMBER(6),
        ABSENT_DAYS   NUMBER(5,2),                      -- the day's share absent: 1 absent, less with leave or a partial absence
        ABSENT_MIN    NUMBER(6),                        -- minutes of absence
        LEAVE_CODES   VARCHAR2(100),
        HOLIDAY       VARCHAR2(100),
        PUNCHES       VARCHAR2(400),                    -- every punch of the day: 07:52 12:30 16:05
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_ATT_DAILY_PK PRIMARY KEY (EMP_CODE, ATT_DATE)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_ATT_DAILY_DATE_IX ON HADER_ATT_DAILY (ATT_DATE, STATUS)';
  END IF;
  -- added in version 1.5: tables created by an earlier script get it in place
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_ATT_DAILY' AND column_name = 'ABSENT_MIN';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_ATT_DAILY ADD (ABSENT_MIN NUMBER(6))';
  END IF;
  -- 1.9.5: the body temperature a thermal terminal took (the punch log shows it)
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'TEMPERATURE';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (TEMPERATURE NUMBER(4,1))';
  END IF;
  -- 2.3.7: when the punch reached the server, on the terminal's clock (the punch log's "arrived after")
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'UPLOADED_AT';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (UPLOADED_AT DATE)';
  END IF;
  -- 2.3.8: a punch whose clock had gone back to midnight, corrected: the time the terminal gave it, and when
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'ORIG_TIME';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (ORIG_TIME DATE, FIXED_AT DATE)';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_EMP_PHOTOS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_EMP_PHOTOS (
        EMP_CODE      VARCHAR2(30)   NOT NULL,
        PHOTO         BLOB,                             -- JPEG
        SOURCE        VARCHAR2(10),                     -- HAND / DEVICE: the card picture; CAPTURE: the recognition photo
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_EMP_PHOTOS_PK PRIMARY KEY (EMP_CODE)
      )]';
  END IF;
  -- added in version 1.6.6: the card picture (shown by the terminals) apart from the recognition photo
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_EMP_PHOTOS' AND column_name = 'SOURCE';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_EMP_PHOTOS ADD (SOURCE VARCHAR2(10))';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_REQUESTS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_REQUESTS (
        REQ_ID        RAW(16)        DEFAULT SYS_GUID() NOT NULL,
        KIND          VARCHAR2(20)   NOT NULL,          -- SYNC, PUNCHES, EMPLOYEES, LEAVES, RECALC
        EMP_CODE      VARCHAR2(30),                     -- RECALC / SYNC: one employee only (optional)
        DATE_FROM     DATE,                             -- RECALC / SYNC / LEAVES: period (default today)
        DATE_TO       DATE,
        REQUESTED_BY  VARCHAR2(100),
        REQUESTED_AT  DATE DEFAULT SYSDATE NOT NULL,
        STATUS        VARCHAR2(10)   DEFAULT 'NEW' NOT NULL,   -- NEW, RUNNING, DONE, FAILED
        STARTED_AT    DATE,
        FINISHED_AT   DATE,
        MESSAGE       VARCHAR2(4000),
        CONSTRAINT HADER_REQUESTS_PK PRIMARY KEY (REQ_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_REQUESTS_ST_IX ON HADER_REQUESTS (STATUS, REQUESTED_AT)';
  END IF;
  -- added in version 1.5.8: a request for one terminal (KIND = DEVICE)
  FOR c IN (SELECT 'DEVICE_SN' col, 'VARCHAR2(50)' def FROM DUAL                -- the terminal's serial number
            UNION ALL SELECT 'ACTION', 'VARCHAR2(30)' FROM DUAL                -- what to do (see HADER_DEVICES below)
            UNION ALL SELECT 'DETAIL', 'VARCHAR2(400)' FROM DUAL) LOOP          -- e.g. 9 face / 1 finger to enroll
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = c.col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS ADD (' || c.col || ' ' || c.def || ')';
    END IF;
  END LOOP;
  -- added in version 1.8.0: the employee portal of APEX app 141 asks Hader for an employee's requests, balances and
  -- inbox (KIND = PORTAL; ACTION mine / leave / manual / overtime / cancel / read; DETAIL the fields as JSON in plain
  -- ASCII, so it may be long) and Hader answers in REPLY (JSON in plain ASCII)
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = 'REPLY';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS ADD (REPLY CLOB)';
  END IF;
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = 'DETAIL'
     AND data_length < 4000;
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS MODIFY (DETAIL VARCHAR2(4000))';
  END IF;
  SELECT COUNT(*) INTO n FROM user_indexes WHERE index_name = 'HADER_REQUESTS_EMP_IX';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_REQUESTS_EMP_IX ON HADER_REQUESTS (EMP_CODE, KIND, REQUESTED_AT)';
  END IF;

  -- added in version 1.6.3, for reports that add up exactly as Hader's: the work days the day counts as,
  -- the share of them attended, the missing check-in / check-out, and the day's first and last punch
  m := 0;
  FOR c IN (SELECT 'WORKDAY' col, 'NUMBER(5,2)' def FROM DUAL UNION ALL SELECT 'PRESENT', 'NUMBER(5,2)' FROM DUAL
            UNION ALL SELECT 'MISSED_IN', 'NUMBER(2)' FROM DUAL UNION ALL SELECT 'MISSED_OUT', 'NUMBER(2)' FROM DUAL
            UNION ALL SELECT 'MISSED_LIST', 'VARCHAR2(200)' FROM DUAL UNION ALL SELECT 'FIRST_PUNCH', 'DATE' FROM DUAL
            UNION ALL SELECT 'LAST_PUNCH', 'DATE' FROM DUAL) LOOP
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_ATT_DAILY' AND column_name = c.col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE HADER_ATT_DAILY ADD (' || c.col || ' ' || c.def || ')';
      m := m + 1;
    END IF;
  END LOOP;
  IF m > 0 THEN   -- the days already there get them on their next calculation: this month and the last one now
    EXECUTE IMMEDIATE q'[INSERT INTO HADER_REQUESTS (KIND, DATE_FROM, DATE_TO, REQUESTED_BY)
                         VALUES ('RECALC', ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1), TRUNC(SYSDATE), 'install 1.6.3')]';
  END IF;

  -- the terminals, as Hader sees them (written every minute while APEX requests are on)
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_DEVICES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_DEVICES (
        SN            VARCHAR2(50)   NOT NULL,
        NAME          VARCHAR2(100),
        AREA_NAME     VARCHAR2(100),
        IP            VARCHAR2(50),
        STATE         VARCHAR2(10),                     -- online, offline, disabled
        MODE_NAME     VARCHAR2(20),                     -- push (the terminal calls Hader) / direct (Hader reads it)
        LAST_CONTACT  DATE,
        LAST_UPLOAD   DATE,                             -- last time it sent punches or people
        MODEL         VARCHAR2(100),
        FIRMWARE      VARCHAR2(100),
        USER_COUNT    NUMBER(8),
        FP_COUNT      NUMBER(8),
        FACE_COUNT    NUMBER(8),
        PALM_COUNT    NUMBER(8),
        ATT_COUNT     NUMBER(10),
        PENDING       NUMBER(8),                        -- commands still owed to it
        READ_ONLY     CHAR(1),                          -- Y: Hader may not write to terminals now
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_DEVICES_PK PRIMARY KEY (SN)
      )]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_DEVICE_COMMANDS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_DEVICE_COMMANDS (
        CMD_ID        NUMBER(12)     NOT NULL,          -- Hader's command number
        DEVICE_SN     VARCHAR2(50)   NOT NULL,
        TITLE         VARCHAR2(120),
        STATUS        VARCHAR2(10),                     -- pending, sent, done, failed
        RETURN_CODE   VARCHAR2(20),                     -- the terminal's answer (0 = done)
        CREATED_AT    DATE,
        SENT_AT       DATE,
        RETURNED_AT   DATE,
        CONSTRAINT HADER_DEVICE_COMMANDS_PK PRIMARY KEY (CMD_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_DEVICE_COMMANDS_SN_IX ON HADER_DEVICE_COMMANDS (DEVICE_SN, CREATED_AT)';
  END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_REQUESTS_BY BEFORE INSERT ON HADER_REQUESTS FOR EACH ROW
BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100);
  ELSIF :NEW.REQUESTED_BY IS NULL OR SYS_CONTEXT('USERENV', 'SESSION_USER') <> SYS_CONTEXT('USERENV', 'CURRENT_USER') THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('USERENV', 'SESSION_USER'), 1, 100);
  END IF;
END;]';
  -- made again over the table as it is now (columns added above): the same text alone would leave it as it was
  EXECUTE IMMEDIATE 'ALTER TRIGGER HADER_REQUESTS_BY COMPILE';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN   -- ORA-01031: this user may not create triggers
    RAISE;
  END IF;
END;
/
COMMENT ON TABLE HADER_PUNCHES IS 'Written by Hader: every punch from the terminals';
COMMENT ON TABLE HADER_ATT_DAILY IS 'Written by Hader: attendance result per employee per day (re-sent when it changes)';
COMMENT ON TABLE HADER_REQUESTS IS 'Written by APEX pages, answered by Hader: sync / recalculation / terminal requests';
COMMENT ON TABLE HADER_DEVICES IS 'Written by Hader: the terminals, their state and counts';
COMMENT ON TABLE HADER_DEVICE_COMMANDS IS 'Written by Hader: commands sent to the terminals in the last days and their answers';
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_DEPARTMENTS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_DEPARTMENTS AS
      SELECT CAST(NULL AS VARCHAR2(50))  AS DEPT_CODE,      -- unique code
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME,      -- Arabic name
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME_EN    -- English name (optional)
        FROM DUAL WHERE 1 = 0]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_EMPLOYEES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_EMPLOYEES AS
      SELECT CAST(NULL AS VARCHAR2(30))  AS EMP_CODE,       -- number used on the terminals
             CAST(NULL AS VARCHAR2(200)) AS FULL_NAME,      -- Arabic full name
             CAST(NULL AS VARCHAR2(160)) AS NAME_EN,        -- English name (optional)
             CAST(NULL AS VARCHAR2(50))  AS DEPT_CODE,      -- = HADER_V_DEPARTMENTS.DEPT_CODE
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME,      -- (optional) used when the department is new
             CAST(NULL AS VARCHAR2(120)) AS POSITION_NAME,  -- job title (optional)
             CAST(NULL AS DATE)          AS HIRE_DATE,      -- (optional)
             CAST(NULL AS VARCHAR2(20))  AS STATUS,         -- A / ACTIVE / 1 = working; anything else = left
             CAST(NULL AS DATE)          AS RESIGN_DATE,    -- (optional)
             CAST(NULL AS VARCHAR2(30))  AS CARD_NO,        -- (optional) badge number
             CAST(NULL AS VARCHAR2(120)) AS EMAIL,          -- (optional) for alerts
             CAST(NULL AS VARCHAR2(50))  AS MOBILE,         -- (optional)
             CAST(NULL AS VARCHAR2(50))  AS AREA_CODE       -- (optional) Hader area = which terminals
        FROM DUAL WHERE 1 = 0]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_LEAVES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_LEAVES AS
      SELECT CAST(NULL AS VARCHAR2(60))  AS LEAVE_ID,       -- unique id in your system
             CAST(NULL AS VARCHAR2(30))  AS EMP_CODE,
             CAST(NULL AS VARCHAR2(10))  AS LEAVE_CODE,     -- e.g. AL, SL
             CAST(NULL AS VARCHAR2(60))  AS LEAVE_NAME,
             CAST(NULL AS DATE)          AS START_TIME,     -- whole days: 00:00 of the first day
             CAST(NULL AS DATE)          AS END_TIME,       -- whole days: 00:00 of the day after the last
             CAST(NULL AS VARCHAR2(20))  AS STATUS          -- APPROVED / PENDING / REJECTED
        FROM DUAL WHERE 1 = 0]';
  END IF;
END;
/
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HDR_EMPLOYEES';
  IF n > 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE OR REPLACE VIEW HADER_V_PEOPLE AS
      SELECT e.EMP_CODE, TO_NCHAR(e.FULL_NAME) AS FULL_NAME, TO_CHAR(e.NAME_EN) AS NAME_EN, e.DEPT_CODE,
             TO_NCHAR(d.NAME) AS DEPT_NAME, TO_CHAR(d.NAME_EN) AS DEPT_NAME_EN, TO_NCHAR(e.POSITION_NAME) AS POSITION_NAME,
             TO_CHAR(e.EMAIL) AS EMAIL, TO_CHAR(e.STATUS) AS STATUS
        FROM HDR_EMPLOYEES e LEFT JOIN HDR_DEPARTMENTS d ON d.DEPT_CODE = e.DEPT_CODE
      UNION ALL
      SELECT TO_CHAR(h.EMP_CODE), TO_NCHAR(h.FULL_NAME), TO_CHAR(h.NAME_EN), TO_CHAR(h.DEPT_CODE),
             TO_NCHAR(NVL(hd.DEPT_NAME, h.DEPT_NAME)), TO_CHAR(hd.DEPT_NAME_EN), TO_NCHAR(h.POSITION_NAME),
             TO_CHAR(h.EMAIL), TO_CHAR(h.STATUS)
        FROM HADER_V_EMPLOYEES h LEFT JOIN HADER_V_DEPARTMENTS hd ON hd.DEPT_CODE = h.DEPT_CODE
       WHERE NOT EXISTS (SELECT 1 FROM HDR_EMPLOYEES x WHERE x.EMP_CODE = TO_CHAR(h.EMP_CODE))]';
  ELSE
    EXECUTE IMMEDIATE q'[
      CREATE OR REPLACE VIEW HADER_V_PEOPLE AS
      SELECT e.EMP_CODE, e.FULL_NAME, e.NAME_EN, e.DEPT_CODE, NVL(d.DEPT_NAME, e.DEPT_NAME) AS DEPT_NAME,
             d.DEPT_NAME_EN, e.POSITION_NAME, e.EMAIL, e.STATUS
        FROM HADER_V_EMPLOYEES e LEFT JOIN HADER_V_DEPARTMENTS d ON d.DEPT_CODE = e.DEPT_CODE]';
  END IF;
END;
/
CREATE OR REPLACE VIEW HADER_V_ATT_REPORT AS
SELECT d.ATT_DATE, d.EMP_CODE, e.FULL_NAME, e.NAME_EN, e.DEPT_CODE,
       e.DEPT_NAME, d.STATUS, d.STATUS_AR, d.STATUS_EN, d.TIMETABLE,
       d.SCHED_IN, d.SCHED_OUT, d.CLOCK_IN, d.CLOCK_OUT, d.REQUIRED_MIN, d.WORKED_MIN, d.LATE_MIN,
       d.EARLY_MIN, d.OT_MIN, d.LEAVE_MIN, d.ABSENT_DAYS, d.ABSENT_MIN, d.LEAVE_CODES, d.HOLIDAY, d.PUNCHES, d.UPDATED_AT,
       -- the status as the program's reports write it: with the holiday's name and the leave codes
       d.STATUS_AR || CASE WHEN d.HOLIDAY IS NOT NULL THEN ' (' || d.HOLIDAY || ')' END
                   || CASE WHEN d.LEAVE_CODES IS NOT NULL THEN ' [' || d.LEAVE_CODES || ']' END AS STATUS_LABEL,
       d.FIRST_PUNCH, d.LAST_PUNCH,
       -- the work days the day counts as and the share attended (a day calculated before 1.6.3: by its status)
       NVL(d.WORKDAY, CASE WHEN d.STATUS IN ('off', 'holiday', 'unscheduled', 'leave') OR d.STATUS IS NULL
                           THEN 0 ELSE 1 END) AS WORKDAY,
       NVL(d.PRESENT, CASE WHEN d.STATUS IN ('present', 'late', 'early', 'late_early', 'incomplete', 'partial_absent')
                           THEN 1 ELSE 0 END) AS PRESENT,
       NVL(d.MISSED_IN, 0) + NVL(d.MISSED_OUT, CASE WHEN d.MISSED_IN IS NULL AND d.STATUS = 'incomplete' THEN 1 ELSE 0 END)
         AS MISSED_PUNCHES,
       NVL(d.MISSED_IN, 0) AS MISSED_IN, NVL(d.MISSED_OUT, 0) AS MISSED_OUT,
       -- the missing punches as the program writes them (a split day can miss two)
       REPLACE(REPLACE(REPLACE(d.MISSED_LIST, 'missed_in', UNISTR('\0628\062F\0648\0646 \062F\062E\0648\0644')),
               'missed_out', UNISTR('\0628\062F\0648\0646 \062E\0631\0648\062C')), ',', UNISTR('\060C ')) AS MISSED_TEXT,
       -- 0/1 flags, so APEX pages never have to list statuses (sum them for counts and rates)
       CASE WHEN d.STATUS IN ('off', 'holiday', 'unscheduled') THEN 0 ELSE 1 END AS IS_EXPECTED,
       CASE WHEN d.STATUS IN ('present', 'late', 'early', 'late_early', 'incomplete', 'partial_absent')
            THEN 1 ELSE 0 END AS IS_PRESENT,
       CASE WHEN d.LATE_MIN > 0 THEN 1 ELSE 0 END AS IS_LATE,
       CASE WHEN d.EARLY_MIN > 0 THEN 1 ELSE 0 END AS IS_EARLY,
       CASE WHEN d.OT_MIN > 0 THEN 1 ELSE 0 END AS IS_OT,
       CASE WHEN d.STATUS = 'absent' THEN 1 ELSE 0 END AS IS_ABSENT,
       CASE WHEN d.STATUS = 'partial_absent' THEN 1 ELSE 0 END AS IS_PARTIAL,
       CASE WHEN d.STATUS = 'leave' THEN 1 ELSE 0 END AS IS_LEAVE,
       CASE WHEN d.STATUS = 'holiday' THEN 1 ELSE 0 END AS IS_HOLIDAY,
       CASE WHEN d.STATUS = 'off' THEN 1 ELSE 0 END AS IS_OFF
  FROM HADER_ATT_DAILY d
  LEFT JOIN HADER_V_PEOPLE e ON e.EMP_CODE = d.EMP_CODE;
CREATE OR REPLACE VIEW HADER_V_MONTH_SUMMARY AS
SELECT TRUNC(ATT_DATE, 'MM') AS MONTH_START, TO_CHAR(ATT_DATE, 'YYYY-MM') AS MONTH, EMP_CODE,
       MAX(FULL_NAME) AS FULL_NAME, MAX(NAME_EN) AS NAME_EN, MAX(DEPT_CODE) AS DEPT_CODE, MAX(DEPT_NAME) AS DEPT_NAME,
       SUM(WORKDAY) AS WORK_DAYS, SUM(PRESENT) AS PRESENT_DAYS, SUM(ABSENT_DAYS) AS ABSENT_DAYS,
       SUM(IS_ABSENT) AS ABSENT_WHOLE_DAYS, SUM(IS_PARTIAL) AS PARTIAL_ABSENT_DAYS, SUM(ABSENT_MIN) AS ABSENT_MIN,
       SUM(IS_LEAVE) AS LEAVE_DAYS, SUM(IS_LATE) AS LATE_TIMES, SUM(LATE_MIN) AS LATE_MIN,
       SUM(IS_EARLY) AS EARLY_TIMES, SUM(EARLY_MIN) AS EARLY_MIN,
       SUM(OT_MIN) AS OT_MIN, SUM(LEAVE_MIN) AS LEAVE_MIN, SUM(WORKED_MIN) AS WORKED_MIN, SUM(REQUIRED_MIN) AS REQUIRED_MIN,
       SUM(MISSED_PUNCHES) AS MISSED_PUNCHES, SUM(IS_HOLIDAY) AS HOLIDAYS, SUM(IS_OFF) AS OFF_DAYS,
       MAX(UPDATED_AT) AS UPDATED_AT
  FROM HADER_V_ATT_REPORT
 GROUP BY TRUNC(ATT_DATE, 'MM'), TO_CHAR(ATT_DATE, 'YYYY-MM'), EMP_CODE;

-- ---------------------------------------------------------------- hader_devices_link.sql
DECLARE
  n NUMBER;
  -- a table (or sequence) is made only when missing; its indexes with it
  PROCEDURE mk(p_name VARCHAR2, p_ddl VARCHAR2, p_ix1 VARCHAR2 DEFAULT NULL, p_ix2 VARCHAR2 DEFAULT NULL,
               p_ix3 VARCHAR2 DEFAULT NULL) IS
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = p_name AND object_type IN ('TABLE', 'SEQUENCE');
    IF n = 0 THEN
      EXECUTE IMMEDIATE p_ddl;
      IF p_ix1 IS NOT NULL THEN EXECUTE IMMEDIATE p_ix1; END IF;
      IF p_ix2 IS NOT NULL THEN EXECUTE IMMEDIATE p_ix2; END IF;
      IF p_ix3 IS NOT NULL THEN EXECUTE IMMEDIATE p_ix3; END IF;
    END IF;
  END;
BEGIN
  mk('HADER_DEV_SEQ', 'CREATE SEQUENCE HADER_DEV_SEQ START WITH 1 INCREMENT BY 1 NOCACHE');
  -- key/value facts: hader.beat (Hader's clock at each round), writing, link.*, set.<device setting> ...
  mk('HADER_DEV_STATE', q'[CREATE TABLE HADER_DEV_STATE (SKEY VARCHAR2(60) NOT NULL, SVALUE VARCHAR2(4000),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_STATE_PK PRIMARY KEY (SKEY))]');
  -- one row per terminal, as the program's device list shows it (never its comm key)
  mk('HADER_DEV_TERMINALS', q'[CREATE TABLE HADER_DEV_TERMINALS (SN VARCHAR2(50) NOT NULL, DEVICE_ID NUMBER(10) NOT NULL,
    NAME VARCHAR2(100), NAME_EN VARCHAR2(100), AREA_ID NUMBER(10), AREA_NAME VARCHAR2(120), IP VARCHAR2(50),
    STATE VARCHAR2(10), ACTIVITY VARCHAR2(12), REQUESTING_WHAT VARCHAR2(400), VIRTUAL_YN CHAR(1), READ_ONLY CHAR(1),
    CONNECTION_MODE VARCHAR2(10), STATUS_DETAIL VARCHAR2(400), DAY_RECON VARCHAR2(400), LAST_CONTACT DATE,
    LAST_UPLOAD DATE, LAST_INIT DATE, MODEL VARCHAR2(100), FIRMWARE VARCHAR2(100), PUSH_VER VARCHAR2(30),
    PLATFORM VARCHAR2(60), MAC VARCHAR2(30), FP_ALG VARCHAR2(20), FACE_ALG VARCHAR2(20), USER_COUNT NUMBER(8),
    FP_COUNT NUMBER(8), FACE_COUNT NUMBER(8), PALM_COUNT NUMBER(8), ATT_COUNT NUMBER(10), PENDING NUMBER(8),
    PEOPLE_EXPECTED NUMBER(8), ENABLED CHAR(1), IS_ATTENDANCE CHAR(1), IS_REGISTRATION CHAR(1), REALTIME CHAR(1),
    TCP_POLL CHAR(1), TIME_ZONE NUMBER(3), HEARTBEAT NUMBER(5), TRANS_INTERVAL NUMBER(5), TRANS_TIMES VARCHAR2(100),
    TCP_PORT NUMBER(6), ALLOWED_IPS VARCHAR2(400), WAITING_YN CHAR(1), MOVED_IP VARCHAR2(50), MOVED_AT DATE,
    MOVED_VIA VARCHAR2(20), BIO_SUPPORT VARCHAR2(400), ATT_STAMP VARCHAR2(30), OP_STAMP VARCHAR2(30), OPTIONS CLOB,
    ROW_HASH VARCHAR2(40), UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_TERMINALS_PK PRIMARY KEY (SN))]');
  mk('HADER_DEV_AREAS', q'[CREATE TABLE HADER_DEV_AREAS (AREA_ID NUMBER(10) NOT NULL, CODE VARCHAR2(50),
    NAME VARCHAR2(120), NAME_EN VARCHAR2(120), DEVICES NUMBER(6), EMPLOYEES NUMBER(8),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_AREAS_PK PRIMARY KEY (AREA_ID))]');
  -- a card, password or privilege a terminal sent, waiting for a person (the value masked as the program shows it)
  mk('HADER_DEV_HELD', q'[CREATE TABLE HADER_DEV_HELD (HELD_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    EMP_CODE VARCHAR2(30), EMP_NAME VARCHAR2(200), FIELD VARCHAR2(20), VALUE_SHOWN VARCHAR2(60), HELD_AT DATE,
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_HELD_PK PRIMARY KEY (HELD_ID))]');
  mk('HADER_DEV_PEOPLE', q'[CREATE TABLE HADER_DEV_PEOPLE (EMP_CODE VARCHAR2(30) NOT NULL, NAME VARCHAR2(200),
    NAME_EN VARCHAR2(200), DEPT VARCHAR2(200), ACTIVE CHAR(1), AREA_IDS VARCHAR2(400), FACES NUMBER(3),
    FINGERS NUMBER(3), PALMS NUMBER(3), PHOTO_YN CHAR(1), ROW_HASH VARCHAR2(40),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_PEOPLE_PK PRIMARY KEY (EMP_CODE))]');
  -- the command log, its content and result redacted as the program's page shows them
  mk('HADER_DEV_COMMANDS', q'[CREATE TABLE HADER_DEV_COMMANDS (CMD_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    TITLE VARCHAR2(120), DIRECTION VARCHAR2(6), STATUS VARCHAR2(10), ATTEMPTS NUMBER(3), RETURN_CODE VARCHAR2(20),
    CONTENT_SHOWN VARCHAR2(200), RESULT_SHOWN VARCHAR2(400), REQ_ID NUMBER(12), CREATED_AT DATE, SENT_AT DATE,
    RETURNED_AT DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_COMMANDS_PK PRIMARY KEY (CMD_ID))]',
    'CREATE INDEX HADER_DEV_COMMANDS_SN_IX ON HADER_DEV_COMMANDS (SN, CREATED_AT)');
  mk('HADER_DEV_OPLOG', q'[CREATE TABLE HADER_DEV_OPLOG (LOG_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    OP_CODE NUMBER(6), ADMIN VARCHAR2(30), OP_TIME DATE, OBJ1 VARCHAR2(50), OBJ2 VARCHAR2(50), OBJ3 VARCHAR2(50),
    OBJ4 VARCHAR2(50), UPLOAD_TIME DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_OPLOG_PK PRIMARY KEY (LOG_ID))]');
  mk('HADER_DEV_ERRLOG', q'[CREATE TABLE HADER_DEV_ERRLOG (LOG_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    ERR_CODE VARCHAR2(20), ERR_MSG VARCHAR2(4000), UPLOAD_TIME DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_ERRLOG_PK PRIMARY KEY (LOG_ID))]');
  mk('HADER_DEV_TRAFFIC', q'[CREATE TABLE HADER_DEV_TRAFFIC (SEQ_NO NUMBER(12) NOT NULL, AT DATE, SN VARCHAR2(50),
    METHOD VARCHAR2(8), PATH VARCHAR2(200), QUERY_TEXT VARCHAR2(1000), BYTES NUMBER(10), REPLY_SHOWN VARCHAR2(1000),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_TRAFFIC_PK PRIMARY KEY (SEQ_NO))]');
  mk('HADER_DEV_RECENT_PUNCHES', q'[CREATE TABLE HADER_DEV_RECENT_PUNCHES (PUNCH_ID NUMBER(12) NOT NULL,
    SN VARCHAR2(50), EMP_CODE VARCHAR2(30), NAME VARCHAR2(200), PUNCH_TIME DATE, STATE_NAME VARCHAR2(40),
    VERIFY_NAME VARCHAR2(40), SOURCE VARCHAR2(10), UPLOADED_AT DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_RECENT_PUNCHES_PK PRIMARY KEY (PUNCH_ID))]');
  mk('HADER_DEV_INTAKE', q'[CREATE TABLE HADER_DEV_INTAKE (BATCH_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    RECEIVED_AT DATE, ACCEPTED NUMBER(8), DUPLICATES NUMBER(8), REJECTED_OPEN NUMBER(8), REPLAYS NUMBER(8),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_INTAKE_PK PRIMARY KEY (BATCH_ID))]');
  -- the terminal-like panel: its saved values each round, the live ones when a panel_read is answered
  mk('HADER_DEV_PANELS', q'[CREATE TABLE HADER_DEV_PANELS (SN VARCHAR2(50) NOT NULL, LIVE_YN CHAR(1), BUSY_YN CHAR(1),
    READ_AT DATE, BODY CLOB, REQ_ID NUMBER(12), UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_PANELS_PK PRIMARY KEY (SN))]');
  -- who may open which page (never trusted by Hader, and no secret in it)
  mk('HADER_DEV_USERS', q'[CREATE TABLE HADER_DEV_USERS (USERNAME VARCHAR2(100) NOT NULL, ACTIVE CHAR(1),
    IS_SUPER CHAR(1), PERMS VARCHAR2(1000), ADMIN_OK CHAR(1), UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_USERS_PK PRIMARY KEY (USERNAME))]');
  mk('HADER_DEV_REQUESTS', q'[CREATE TABLE HADER_DEV_REQUESTS (REQ_ID NUMBER(12) NOT NULL, BATCH_ID NUMBER(12),
    CATEGORY VARCHAR2(10) NOT NULL, ACTION VARCHAR2(40) NOT NULL, SN VARCHAR2(50), TARGET_ID NUMBER(12),
    PARAMS VARCHAR2(4000), REQUESTED_BY VARCHAR2(100), REQUESTED_AT DATE DEFAULT SYSDATE NOT NULL,
    STATUS VARCHAR2(10) DEFAULT 'NEW' NOT NULL, PICKED_AT DATE, FINISHED_AT DATE, HTTP_CODE NUMBER(4),
    MESSAGE VARCHAR2(4000), REPLY CLOB, CONSTRAINT HADER_DEV_REQUESTS_PK PRIMARY KEY (REQ_ID),
    CONSTRAINT HADER_DEV_REQUESTS_ST CHECK (STATUS IN ('NEW','RUNNING','DONE','FAILED','EXPIRED','CANCELLED')))]',
    'CREATE INDEX HADER_DEV_REQUESTS_ST_IX ON HADER_DEV_REQUESTS (STATUS, REQ_ID)',
    'CREATE INDEX HADER_DEV_REQUESTS_BATCH_IX ON HADER_DEV_REQUESTS (BATCH_ID)',
    'CREATE INDEX HADER_DEV_REQUESTS_BY_IX ON HADER_DEV_REQUESTS (REQUESTED_BY, REQUESTED_AT)');
END;
/
BEGIN
  FOR t IN (SELECT table_name FROM user_tables WHERE table_name IN ('HADER_DEV_STATE', 'HADER_DEV_TERMINALS',
              'HADER_DEV_AREAS', 'HADER_DEV_HELD', 'HADER_DEV_PEOPLE', 'HADER_DEV_COMMANDS', 'HADER_DEV_OPLOG',
              'HADER_DEV_ERRLOG', 'HADER_DEV_TRAFFIC', 'HADER_DEV_RECENT_PUNCHES', 'HADER_DEV_INTAKE',
              'HADER_DEV_PANELS', 'HADER_DEV_USERS')) LOOP
    EXECUTE IMMEDIATE 'CREATE OR REPLACE TRIGGER ' || SUBSTR(t.table_name, 1, 27) || '_RO BEFORE INSERT OR UPDATE OR DELETE ON '
      || t.table_name || q'[ BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    RAISE_APPLICATION_ERROR(-20690, 'Written by Hader only');
  END IF;
END;]';
  END LOOP;
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN
    RAISE;
  END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_DEV_REQUESTS_BY BEFORE INSERT ON HADER_DEV_REQUESTS FOR EACH ROW
BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100);
  ELSIF :NEW.REQUESTED_BY IS NULL OR SYS_CONTEXT('USERENV', 'SESSION_USER') <> SYS_CONTEXT('USERENV', 'CURRENT_USER') THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('USERENV', 'SESSION_USER'), 1, 100);
  END IF;
  IF :NEW.REQ_ID IS NULL THEN
    SELECT HADER_DEV_SEQ.NEXTVAL INTO :NEW.REQ_ID FROM DUAL;
  END IF;
  :NEW.STATUS := 'NEW';
  :NEW.REQUESTED_AT := SYSDATE;
  :NEW.PICKED_AT := NULL;
  :NEW.FINISHED_AT := NULL;
  :NEW.HTTP_CODE := NULL;
  :NEW.MESSAGE := NULL;
  :NEW.REPLY := NULL;
END;]';
  -- from an APEX session the only change is the asker's own waiting request cancelled; never a delete
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_DEV_REQUESTS_UPD BEFORE UPDATE OR DELETE ON HADER_DEV_REQUESTS FOR EACH ROW
BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    IF DELETING OR :OLD.STATUS <> 'NEW' OR :NEW.STATUS <> 'CANCELLED'
       OR NVL(:OLD.REQUESTED_BY, '-') <> SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100) THEN
      RAISE_APPLICATION_ERROR(-20691, 'Only your own waiting request can be cancelled');
    END IF;
    :NEW.REQ_ID := :OLD.REQ_ID; :NEW.BATCH_ID := :OLD.BATCH_ID; :NEW.CATEGORY := :OLD.CATEGORY;
    :NEW.ACTION := :OLD.ACTION; :NEW.SN := :OLD.SN; :NEW.TARGET_ID := :OLD.TARGET_ID; :NEW.PARAMS := :OLD.PARAMS;
    :NEW.REQUESTED_BY := :OLD.REQUESTED_BY; :NEW.REQUESTED_AT := :OLD.REQUESTED_AT; :NEW.FINISHED_AT := SYSDATE;
    -- nor an answer of its own making: what a cancelled row says comes from Hader only
    :NEW.PICKED_AT := :OLD.PICKED_AT; :NEW.HTTP_CODE := :OLD.HTTP_CODE; :NEW.MESSAGE := :OLD.MESSAGE;
    :NEW.REPLY := :OLD.REPLY;
  END IF;
END;]';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN
    RAISE;
  END IF;
END;
/

-- ---------------------------------------------------------------- hdr_dev_ui.pks
CREATE OR REPLACE PACKAGE HDR_DEV_UI AS
  -- =====================================================================================
  --  The "Hader Terminals" APEX app's one door to the terminals' link tables (hader_devices_link.sql).
  --
  --  It reads only the HADER_DEV_* tables Hader publishes (and HADER_PUNCHES for the punch log) and writes only
  --  HADER_DEV_REQUESTS: one row per command, decision, setting or read, which the Hader server runs through its
  --  own web endpoint as the Hader account of the APEX user's name, and answers in the same row.
  --  It never calls the gateway's packages (the terminals belong to Hader here, not to this database).
  --  Its checks (may, the whitelist) only spare a person a request Hader would refuse: Hader checks every
  --  request again with the permissions of its own account.
  --  Answers are JSON in plain ASCII (\u escapes) whatever the database character set; the device list has the
  --  keys of HDR_UI.devices, so the terminals plug-in draws either.
  --  Errors are raised as ORA-2069x with an Arabic - English message for the page.
  -- =====================================================================================

  c_open_max      CONSTANT PLS_INTEGER := 60;   -- open requests one person may have at a time
  c_stale_seconds CONSTANT PLS_INTEGER := 30;   -- at least this long without a beat: Hader is not there

  -- who asks: the APEX user signed in, else (a script of this schema's own) the name act_as set, else the
  -- database user. act_as is refused inside an APEX session: there the APEX user is the only name.
  FUNCTION me RETURN VARCHAR2;
  PROCEDURE act_as (p_user IN VARCHAR2);

  -- Y / N: the user's Hader account holds the permission (as Hader last published it); 'superuser' for a super
  -- administrator. A permission that changes something is N while Hader cannot be reached.
  FUNCTION may (p_perm IN VARCHAR2) RETURN VARCHAR2;
  -- 'CATEGORY permission' of an action Hader runs, else NULL (generated from the Hader server's own list)
  FUNCTION rule (p_action IN VARCHAR2) RETURN VARCHAR2;

  FUNCTION state (p_key IN VARCHAR2) RETURN VARCHAR2;     -- a fact Hader published (HADER_DEV_STATE)
  FUNCTION beat_age RETURN NUMBER;                        -- seconds since Hader's last round; NULL: never
  FUNCTION reachable RETURN VARCHAR2;                     -- Y / N
  FUNCTION hader_now RETURN DATE;                         -- Hader's clock now (the times it publishes are its own)

  -- one request; returns its number. p_params: a JSON object in ASCII (\u escapes), at most 4000 characters.
  FUNCTION ask (p_action IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL, p_params IN VARCHAR2 DEFAULT NULL,
                p_target IN NUMBER DEFAULT NULL, p_batch IN NUMBER DEFAULT NULL) RETURN NUMBER;
  -- the same request for several terminals ('SN:SN:SN'), one batch; returns the batch number
  FUNCTION ask_many (p_action IN VARCHAR2, p_sns IN VARCHAR2, p_params IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- {"id","status","code","message","action","sn","reply"}: the asker's own request only
  FUNCTION status (p_req IN NUMBER) RETURN CLOB;
  -- {"batch","total","open","done","failed",...,"rows":[{sn,status,code,message}]}
  FUNCTION batch_status (p_batch IN NUMBER) RETURN CLOB;
  PROCEDURE cancel (p_req IN NUMBER);                     -- one's own request, while it still waits

  -- what the pages and the terminals plug-in draw ---------------------------------------------------------
  FUNCTION devices RETURN CLOB;                           -- the keys of HDR_UI.devices, and more
  FUNCTION device (p_sn IN VARCHAR2) RETURN CLOB;         -- one terminal: every published field, its options
  FUNCTION commands (p_sn IN VARCHAR2, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;
  FUNCTION traffic (p_sn IN VARCHAR2 DEFAULT NULL, p_limit IN NUMBER DEFAULT 300) RETURN CLOB;
  FUNCTION punches (p_sn IN VARCHAR2, p_limit IN NUMBER DEFAULT 60) RETURN CLOB;   -- today's, on one terminal
  FUNCTION panel (p_sn IN VARCHAR2) RETURN CLOB;          -- the terminal-like panel's values (JSON or null)
  FUNCTION people (p_q IN VARCHAR2 DEFAULT NULL, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;   -- the picker
  -- the program's lists of the devices module, a page at a time: {"total","rows":[...]} with its keys
  FUNCTION oplog (p_sn IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0, p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  FUNCTION errlog (p_sn IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0, p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  FUNCTION intake (p_sn IN VARCHAR2 DEFAULT NULL, p_rejected IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0,
                   p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  -- the punch log (HADER_PUNCHES): p_from / p_to 'YYYY-MM-DD', p_sn a terminal, p_dept a department name, p_q an
  -- employee number or name
  FUNCTION punch_log (p_from IN VARCHAR2, p_to IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL, p_dept IN VARCHAR2 DEFAULT NULL,
                      p_q IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0, p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  FUNCTION departments RETURN CLOB;                       -- {"rows":[{"id","name"}]}: the departments of the people
  -- what the native pages of the app show and send (apex/build_terminals_app.py) ------------------------------
  -- one published field of a terminal by its column name in HADER_DEV_TERMINALS (never its comm key)
  FUNCTION field (p_sn IN VARCHAR2, p_col IN VARCHAR2) RETURN VARCHAR2;
  -- one of the terminal's settings as it last reported it (the panel read, else its options); p_keys 'A|B': the
  -- names the terminals answer it under, the first one found wins
  FUNCTION opt (p_sn IN VARCHAR2, p_keys IN VARCHAR2) RETURN VARCHAR2;
  -- the name of p_keys this terminal reports (the first when it reports none): the one a change is written to
  FUNCTION opt_key (p_sn IN VARCHAR2, p_keys IN VARCHAR2) RETURN VARCHAR2;
  -- '"key":value,' for a JSON object, nothing when the value is null. p_kind: S text, N number, B Y/N as a
  -- boolean, L a list of texts from 'a:b:c'
  FUNCTION pair (p_key IN VARCHAR2, p_value IN NVARCHAR2, p_kind IN VARCHAR2 DEFAULT 'S') RETURN VARCHAR2;
  -- the pair of a setting, only when the new value differs from what the terminal reported
  FUNCTION change (p_sn IN VARCHAR2, p_keys IN VARCHAR2, p_value IN NVARCHAR2) RETURN VARCHAR2;
  -- '{pairs}', or '{"wrap":{pairs}}'; NULL when there is no pair and no wrap (nothing to send)
  FUNCTION obj (p_pairs IN VARCHAR2, p_wrap IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION first_sn (p_sns IN VARCHAR2) RETURN VARCHAR2;  -- the first of 'SN:SN:SN', refused when none
  -- the line a page shows for one of the asker's requests or batches: status and Hader's message
  FUNCTION said (p_req IN NUMBER) RETURN VARCHAR2;
  FUNCTION said_batch (p_batch IN NUMBER) RETURN VARCHAR2;
  -- the answer of one of the asker's READ requests (its first 4000 characters)
  FUNCTION reply_text (p_req IN NUMBER) RETURN VARCHAR2;
END HDR_DEV_UI;
/

