-- ---------------------------------------------------------------- hdr_schema.sql
DECLARE
  n NUMBER;
  PROCEDURE ddl (p_name IN VARCHAR2, p_sql IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = p_name;
    IF n = 0 THEN
      EXECUTE IMMEDIATE p_sql;
    END IF;
  END;
  PROCEDURE col (p_table IN VARCHAR2, p_col IN VARCHAR2, p_def IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = p_table AND column_name = p_col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_col || ' ' || p_def || ')';
    END IF;
  END;
BEGIN
  ddl('HDR_SEQ', 'CREATE SEQUENCE HDR_SEQ CACHE 100');

  -- ---------------------------------------------------------------- settings
  ddl('HDR_SETTINGS', q'[
    CREATE TABLE HDR_SETTINGS (
      SKEY   VARCHAR2(60) NOT NULL,
      SVALUE VARCHAR2(4000),
      CONSTRAINT HDR_SETTINGS_PK PRIMARY KEY (SKEY))]');

  -- the English of APEX app 141's own words (2.3.6): its pages, items and buttons are written in Arabic and their
  -- English is a translation of them (HDR_UI.publish_english); filled by hdr_i18n.sql from apex/i18n/ar_en.json
  ddl('HDR_I18N', q'[
    CREATE TABLE HDR_I18N (
      AR NVARCHAR2(1000) NOT NULL,
      EN VARCHAR2(2000)  NOT NULL,
      CONSTRAINT HDR_I18N_PK PRIMARY KEY (AR))]');

  -- ---------------------------------------------------------------- people
  ddl('HDR_AREAS', q'[
    CREATE TABLE HDR_AREAS (
      AREA_ID    NUMBER        NOT NULL,
      AREA_CODE  VARCHAR2(50)  NOT NULL,
      NAME       NVARCHAR2(120) NOT NULL,
      NAME_EN    VARCHAR2(120),
      CONSTRAINT HDR_AREAS_PK PRIMARY KEY (AREA_ID),
      CONSTRAINT HDR_AREAS_UK UNIQUE (AREA_CODE))]');

  ddl('HDR_DEPARTMENTS', q'[
    CREATE TABLE HDR_DEPARTMENTS (
      DEPT_CODE   VARCHAR2(50)   NOT NULL,
      NAME        NVARCHAR2(120) NOT NULL,
      NAME_EN     VARCHAR2(120),
      PARENT_CODE VARCHAR2(50),
      CONSTRAINT HDR_DEPARTMENTS_PK PRIMARY KEY (DEPT_CODE))]');

  ddl('HDR_EMPLOYEES', q'[
    CREATE TABLE HDR_EMPLOYEES (
      EMP_ID        NUMBER         NOT NULL,
      EMP_CODE      VARCHAR2(30)   NOT NULL,          -- the number used on the terminals (PIN)
      FULL_NAME     NVARCHAR2(200),
      NAME_EN       VARCHAR2(160),
      DEPT_CODE     VARCHAR2(50),
      POSITION_NAME NVARCHAR2(120),
      HIRE_DATE     DATE,
      STATUS        VARCHAR2(10)   DEFAULT 'active' NOT NULL,   -- active / resigned
      RESIGN_DATE   DATE,
      CARD_NO       VARCHAR2(30),
      DEV_PASSWORD  VARCHAR2(30),
      DEV_PRIVILEGE NUMBER(3)      DEFAULT 0 NOT NULL,          -- 0 user, 14 terminal administrator
      VERIFY_MODE   NUMBER(3)      DEFAULT -1 NOT NULL,         -- -1 = terminal default
      ENABLE_ATT    CHAR(1)        DEFAULT 'Y' NOT NULL,
      EMAIL         VARCHAR2(120),
      MOBILE        VARCHAR2(50),
      SOURCE        VARCHAR2(10)   DEFAULT 'LOCAL' NOT NULL,    -- HR / LOCAL / DEVICE
      CREATED_AT    DATE           DEFAULT SYSDATE NOT NULL,
      UPDATED_AT    DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_EMPLOYEES_PK PRIMARY KEY (EMP_ID),
      CONSTRAINT HDR_EMPLOYEES_UK UNIQUE (EMP_CODE))]');
  ddl('HDR_EMPLOYEES_DEPT_IX', 'CREATE INDEX HDR_EMPLOYEES_DEPT_IX ON HDR_EMPLOYEES (DEPT_CODE, STATUS)');

  ddl('HDR_EMP_AREAS', q'[
    CREATE TABLE HDR_EMP_AREAS (
      EMP_CODE VARCHAR2(30) NOT NULL,
      AREA_ID  NUMBER       NOT NULL,
      CONSTRAINT HDR_EMP_AREAS_PK PRIMARY KEY (EMP_CODE, AREA_ID))]');
  ddl('HDR_EMP_AREAS_AREA_IX', 'CREATE INDEX HDR_EMP_AREAS_AREA_IX ON HDR_EMP_AREAS (AREA_ID)');

  -- BIODATA types: 1 fingerprint, 2 near-infrared face, 7 finger vein, 8 palm, 9 visible-light face
  ddl('HDR_BIO', q'[
    CREATE TABLE HDR_BIO (
