      TEMPLATE   CLOB          NOT NULL,                 -- base64, as the terminal sends it
      SOURCE_SN  VARCHAR2(50),
      UPDATED_AT DATE          DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_BIO_PK PRIMARY KEY (BIO_ID),
      CONSTRAINT HDR_BIO_UK UNIQUE (EMP_CODE, BIO_TYPE, BIO_NO, BIO_INDEX, MAJOR_VER))]');

  ddl('HDR_BIO_PHOTOS', q'[
    CREATE TABLE HDR_BIO_PHOTOS (
