      OP_STAMP       VARCHAR2(30)   DEFAULT '0' NOT NULL,
      PHOTO_STAMP    VARCHAR2(30)   DEFAULT '0' NOT NULL,
      TODAY_STATE    VARCHAR2(400),                           -- request for today's punches kept on the terminal
      LAST_ACTIVITY  DATE,
