  -- a terminal back after a silence (power or network cut), on its own clock (as HADER_PUNCHES): the punches it
  -- kept before its clock was set again are looked for from here (HDR_V_RETURN_PUNCHES, HDR_UI.clock_fix)
  ddl('HDR_RETURNS', q'[
    CREATE TABLE HDR_RETURNS (
      RETURN_ID      NUMBER        NOT NULL,
      SN             VARCHAR2(50)  NOT NULL,
      RETURNED_AT    DATE          NOT NULL,
