      FIXED_BY       VARCHAR2(100),
      FIXED_AT       DATE,
      CLOCK_AT       DATE,
      CONSTRAINT HDR_RETURNS_PK PRIMARY KEY (RETURN_ID))]');
  col('HDR_RETURNS', 'CLOCK_AT', 'DATE');      -- its clock set on this return (the bell says so once, HDR_ALERTS)
  ddl('HDR_RETURNS_IX', 'CREATE INDEX HDR_RETURNS_IX ON HDR_RETURNS (STATUS, RETURNED_AT)');

  ddl('HDR_ERRLOG', q'[
    CREATE TABLE HDR_ERRLOG (
