      CONSTRAINT HDR_ERRLOG_PK PRIMARY KEY (LOG_ID))]');

  -- every request of the terminals (communication monitor; kept a few days)
  ddl('HDR_TRAFFIC', q'[
    CREATE TABLE HDR_TRAFFIC (
