  ddl('HDR_TRAFFIC_AT_IX', 'CREATE INDEX HDR_TRAFFIC_AT_IX ON HDR_TRAFFIC (SN, LOGGED_AT)');

  -- punch lines a terminal sent that could not be stored (the inbox)
  -- 2.3.6: what a terminal sent that would change a person kept here (a card, a password, a higher privilege),
  -- held until a person decides (HDR_UI device_do held_accept / held_reject): a terminal is known by its serial
  -- number and address only, so it never raises a privilege nor replaces a card or a password by itself
  ddl('HDR_HELD', q'[
    CREATE TABLE HDR_HELD (
      HELD_ID    NUMBER        NOT NULL,
