      LINE_NO NUMBER,
      REASON  VARCHAR2(40),
      LINE    VARCHAR2(1000),
      CONSTRAINT HDR_REJECTS_PK PRIMARY KEY (LOG_ID))]');

  -- employee-days whose attendance must be calculated again (new punches, leave, schedule changes)
  ddl('HDR_DIRTY', q'[
    CREATE TABLE HDR_DIRTY (
      EMP_CODE VARCHAR2(30) NOT NULL,
      ATT_DATE DATE         NOT NULL,
      MARKED_AT DATE        DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_DIRTY_PK PRIMARY KEY (EMP_CODE, ATT_DATE))]');

  -- ---------------------------------------------------------------- attendance rules
  -- times are 'HH24:MI'; minutes are whole minutes
  ddl('HDR_TIMETABLES', q'[
    CREATE TABLE HDR_TIMETABLES (
      TT_ID        NUMBER         NOT NULL,
      ALIAS        NVARCHAR2(60)  NOT NULL,
      KIND         VARCHAR2(10)   DEFAULT 'normal' NOT NULL,   -- normal / flexible
      CHECK_IN     VARCHAR2(5)    DEFAULT '08:00' NOT NULL,
      CHECK_OUT    VARCHAR2(5)    DEFAULT '16:00' NOT NULL,
      IN_AHEAD     NUMBER(5)      DEFAULT 120 NOT NULL,        -- check-in accepted from .. minutes before
      IN_ABOVE     NUMBER(5)      DEFAULT 240 NOT NULL,        -- .. until .. minutes after
      OUT_AHEAD    NUMBER(5)      DEFAULT 240 NOT NULL,
      OUT_ABOVE    NUMBER(5)      DEFAULT 240 NOT NULL,
      LATE_GRACE   NUMBER(5)      DEFAULT 0 NOT NULL,
      EARLY_GRACE  NUMBER(5)      DEFAULT 0 NOT NULL,
      MUST_IN      CHAR(1)        DEFAULT 'Y' NOT NULL,
      MUST_OUT     CHAR(1)        DEFAULT 'Y' NOT NULL,
      BREAK_START  VARCHAR2(5),
      BREAK_END    VARCHAR2(5),
      WORK_MINUTES NUMBER(5)      DEFAULT 480 NOT NULL,        -- flexible: minutes required in the day
      WORKDAY      NUMBER(4,2)    DEFAULT 1 NOT NULL,          -- counts as .. work days
      COLOR        VARCHAR2(10)   DEFAULT '#1e88e5',
      CONSTRAINT HDR_TIMETABLES_PK PRIMARY KEY (TT_ID),
      CONSTRAINT HDR_TIMETABLES_UK UNIQUE (ALIAS))]');

  ddl('HDR_SHIFTS', q'[
    CREATE TABLE HDR_SHIFTS (
