      CONSTRAINT HDR_SCHEDULES_PK PRIMARY KEY (SCHED_ID))]');
  ddl('HDR_SCHEDULES_EMP_IX', 'CREATE INDEX HDR_SCHEDULES_EMP_IX ON HDR_SCHEDULES (EMP_CODE, START_DATE, END_DATE)');

  ddl('HDR_DEPT_SCHEDULES', q'[
