      TT_ID    NUMBER,
      CONSTRAINT HDR_TEMP_SCHEDULES_PK PRIMARY KEY (TEMP_ID))]');
  ddl('HDR_TEMP_SCHEDULES_IX', 'CREATE INDEX HDR_TEMP_SCHEDULES_IX ON HDR_TEMP_SCHEDULES (EMP_CODE, ATT_DATE)');

  ddl('HDR_HOLIDAYS', q'[
    CREATE TABLE HDR_HOLIDAYS (
      HOLIDAY_ID NUMBER         NOT NULL,
