      START_DATE DATE           NOT NULL,
      DAYS       NUMBER(3)      DEFAULT 1 NOT NULL,
      DEPT_CODE  VARCHAR2(50),                             -- empty = everyone
      CONSTRAINT HDR_HOLIDAYS_PK PRIMARY KEY (HOLIDAY_ID))]');

  ddl('HDR_LEAVE_TYPES', q'[
    CREATE TABLE HDR_LEAVE_TYPES (
      LEAVE_CODE  VARCHAR2(10)  NOT NULL,
      NAME        NVARCHAR2(60) NOT NULL,
      NAME_EN     VARCHAR2(120),
      PAID        CHAR(1)       DEFAULT 'Y' NOT NULL,
      COLOR       VARCHAR2(10)  DEFAULT '#8e24aa',
      ANNUAL_DAYS NUMBER(4)     DEFAULT 0 NOT NULL,
      CONSTRAINT HDR_LEAVE_TYPES_PK PRIMARY KEY (LEAVE_CODE))]');

  ddl('HDR_LEAVES', q'[
    CREATE TABLE HDR_LEAVES (
      LEAVE_ID   NUMBER         NOT NULL,
      EMP_CODE   VARCHAR2(30)   NOT NULL,
      LEAVE_CODE VARCHAR2(10)   NOT NULL,
      START_TIME DATE           NOT NULL,                  -- whole days: 00:00 of the first day
      END_TIME   DATE           NOT NULL,                  -- whole days: 00:00 of the day after the last
      REASON     NVARCHAR2(250),
      STATUS     VARCHAR2(10)   DEFAULT 'approved' NOT NULL,   -- pending / approved / rejected
      APPROVER   VARCHAR2(100),
      SOURCE     VARCHAR2(10)   DEFAULT 'admin' NOT NULL,      -- admin / hr
      EXT_REF    VARCHAR2(70),                             -- id in the HR system
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_LEAVES_PK PRIMARY KEY (LEAVE_ID))]');
  ddl('HDR_LEAVES_EMP_IX', 'CREATE INDEX HDR_LEAVES_EMP_IX ON HDR_LEAVES (EMP_CODE, START_TIME)');
  ddl('HDR_LEAVES_REF_IX', 'CREATE INDEX HDR_LEAVES_REF_IX ON HDR_LEAVES (EXT_REF)');
  -- the requests waiting (counts on the dashboard, alerts every minute): a few index blocks, not every row
  ddl('HDR_LEAVES_ST_IX', 'CREATE INDEX HDR_LEAVES_ST_IX ON HDR_LEAVES (STATUS, CREATED_AT)');

  -- forgotten punches entered by hand, counted once approved
  ddl('HDR_MANUAL_PUNCHES', q'[
    CREATE TABLE HDR_MANUAL_PUNCHES (
      MANUAL_ID   NUMBER         NOT NULL,
      EMP_CODE    VARCHAR2(30)   NOT NULL,
      PUNCH_TIME  DATE           NOT NULL,
