  USING (SELECT UNISTR('+ \0645\0633\0624\0648\0644 \0627\0639\062A\0645\0627\062F') AR, '+ Approver' EN FROM DUAL
UNION ALL SELECT UNISTR('- \0627\062E\062A\0631 -') AR, '- Choose -' EN FROM DUAL
UNION ALL SELECT UNISTR('- \0627\062E\062A\0631 \0627\0644\062C\0647\0627\0632 -') AR, '- Choose a device -' EN FROM DUAL
UNION ALL SELECT UNISTR('- \0627\062E\062A\0631 \0627\0644\0642\0633\0645 -') AR, '- Choose a department -' EN FROM DUAL
