UNION ALL SELECT UNISTR('\064A\064F\0639\0631\0641 \0627\0644\0645\0648\0638\0641 \0628\0640') AR, 'Employee is identified by' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0642\0628\0644 \0627\0644\062E\0631\0648\062C \0642\0628\0644 \0627\0644\0645\0648\0639\062F \0628\0640 (\062F\0642\064A\0642\0629)') AR, 'Check-out accepted before the time by (min)' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0642\0628\0644 \0627\0644\062F\062E\0648\0644 \0642\0628\0644 \0627\0644\0645\0648\0639\062F \0628\0640 (\062F\0642\064A\0642\0629)') AR, 'Check-in accepted before the time by (min)' EN FROM DUAL) s ON (t.AR = s.AR)
  WHEN MATCHED THEN UPDATE SET EN = s.EN WHERE t.EN <> s.EN
  WHEN NOT MATCHED THEN INSERT (AR, EN) VALUES (s.AR, s.EN);
  COMMIT;
END;
